files = repo.list("src")
contents = {}
for f in files:
    if f.endswith("/"):
        continue
    contents[f] = repo.read("src/" + f)

# case-insensitive sweep to be sure nothing is missed
ci = repo.search(r"(?i)\b(todo|fixme|xxx|hack)\b", glob = "src/**")
ci_out = [{"path": h.path, "line": h.line, "text": h.text} for h in ci]

numbered = {}
for name, body in contents.items():
    lines = body.split("\n")
    numbered[name] = ["%d: %s" % (i + 1, l) for i, l in enumerate(lines)]

return {"files": files, "numbered": numbered, "case_insensitive_hits": ci_out}
